348	export type Field = Node<'field'>;
349	export type NameLiteral = Node<'name'>;
350	
351	/** An expression of PT2.2; the checker types it. */
352	export type Expr = any;
353	/** The parameter of an arrow: every name of the program is a property of it. */
354	export type Scope = any;
355	export type Arrow<T = Expr> = (scope: Scope) => T;
356	export type Args = Expr[] | { [name: string]: Expr };
357	export type Literal = number | string | boolean | NameLiteral;
358	export type Mode = 'strict' | 'disclosed';
359	
360	export interface Type {
361	  /** A parameter's check clause: a set of literals, or a range, and its mode. */
362	  check(values: Literal[], mode?: Mode): Type;
363	  check(lo: number, hi: number, mode?: Mode): Type;
364	}
365	
366	export declare const t: {
367	  readonly bool: Type;
368	  readonly int: Type;
369	  readonly string: Type;
370	  range(lo: number, hi: number): Type;
371	  named(name: string): Type;
372	  map(key: Type, value: Type): Type;
373	  ref(machine: string): Type;
