import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };

test('place, confirm, messages', async () => {
  const h = await createHost();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.deepEqual(await h.place('a', 1), ok);
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 1 });
  const m = await h.inFlight();
  assert.equal(m.length, 1);
  assert.deepEqual({ ...m[0], id: undefined }, { id: undefined, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 1 } });
  await h.deliver(m[0].id);
  const r = await h.inFlight();
  assert.deepEqual(r.map((x) => [x.from, x.to, x.action, x.data]), [['inventory', 'a', 'Reserved', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'confirmed', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1, open: true });
  assert.deepEqual(await h.cancel('a'), ok);
  assert.deepEqual((await h.inFlight()).map((x) => [x.action, x.data]), [['Release', { qty: 1 }]]);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'cancelled', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal((await h.cancel('a')).ok, false);
});

test('refusals', async () => {
  const h = await createHost();
  assert.equal((await h.place('a', 3)).ok, false);
  assert.equal((await h.place('a', 0)).ok, false);
  assert.equal(await h.order('a'), null);
  assert.equal((await h.cancel('zz')).ok, false);
  assert.equal(await h.order('zz'), null);
  assert.deepEqual(await h.place('a', 2), ok);
  assert.equal((await h.place('a', 1)).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 2 });
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'rejected', qty: 2 });
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.restock(), ok);
  assert.deepEqual(await h.restock(), ok);
  assert.equal((await h.restock()).ok, false);
  assert.deepEqual(await h.stock(), { available: 3, reserved: 0, open: true });
});

test('expire', async () => {
  const h = await createHost();
  assert.equal((await h.expire('zz')).ok, false);
  await h.place('a', 1);
  assert.equal((await h.expire('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.expire('a'), ok);
  assert.deepEqual(await h.order('a'), { status: 'expired', qty: 1 });
  assert.deepEqual((await h.inFlight()).map((x) => [x.from, x.to, x.action, x.data]), [['a', 'inventory', 'Release', { qty: 1 }]]);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.equal((await h.expire('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.place('a', 1)).ok, false);
  await h.place('b', 1);
  await h.cancel('b');
  assert.equal((await h.expire('b')).ok, false);
});

test('close for a stocktake', async () => {
  const h = await createHost();
  assert.equal((await h.open()).ok, false);
  await h.place('a', 1);
  await h.deliverAll();
  assert.deepEqual(await h.restock(), ok);
  assert.deepEqual(await h.close(), ok);
  assert.equal((await h.close()).ok, false);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 1, open: false });
  assert.equal((await h.restock()).ok, false);
  await h.place('b', 1);
  await h.deliverAll();
  assert.deepEqual(await h.order('b'), { status: 'rejected', qty: 1 });
  assert.deepEqual(await h.cancel('a'), ok);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0, open: false });
  assert.deepEqual(await h.open(), ok);
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0, open: true });
  await h.place('c', 2);
  await h.deliverAll();
  assert.deepEqual(await h.order('c'), { status: 'confirmed', qty: 2 });
});

test('cancel while pending', async () => {
  const h = await createHost();
  await h.place('a', 1);
  assert.deepEqual(await h.cancel('a'), ok);
  assert.deepEqual(await h.order('a'), { status: 'cancelling', qty: 1 });
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'cancelled', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  await h.place('b', 2);
  await h.cancel('b');
  await h.deliverAll();
  assert.deepEqual(await h.order('b'), { status: 'cancelled', qty: 2 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
});
